function search(nums, target) {
  let lo = 0;
  let hi = nums.length - 1; // search space is the closed interval [lo, hi]
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2); // overflow-safe midpoint
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) lo = mid + 1; // target can only be right of mid
    else hi = mid - 1; // target can only be left of mid
  }
  return -1; // [lo, hi] is empty: target is not present
}

def search(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1  # closed interval [lo, hi]
    while lo <= hi:
        mid = (lo + hi) // 2  # Python ints never overflow
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1  # target can only be right of mid
        else:
            hi = mid - 1  # target can only be left of mid
    return -1  # [lo, hi] is empty: target is not present

public int search(int[] nums, int target) {
    int lo = 0, hi = nums.length - 1; // closed interval [lo, hi]
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2; // (lo + hi) / 2 can overflow int
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) lo = mid + 1; // target is right of mid
        else hi = mid - 1; // target is left of mid
    }
    return -1; // [lo, hi] is empty: target is not present
}

function searchInsert(nums, target) {
  let lo = 0;
  let hi = nums.length; // half-open [lo, hi): the answer may be nums.length
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (nums[mid] < target) lo = mid + 1; // mid is too small: answer is right of it
    else hi = mid; // nums[mid] >= target: mid itself may be the answer
  }
  return lo; // lo === hi: first index with nums[i] >= target
}

