  let lo = 0;
  let hi = nums.length - 1;
  let ans = -1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (nums[mid] === target) {
      ans = mid; // record it, but keep searching one side
      if (isFirst) hi = mid - 1; // an earlier copy may exist on the left
      else lo = mid + 1; // a later copy may exist on the right
    } else if (nums[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return ans;
}

