function findMin(nums) {
  let lo = 0;
  let hi = nums.length - 1;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (nums[mid] > nums[hi]) {
      lo = mid + 1; // the drop (minimum) is strictly right of mid
    } else {
      hi = mid; // [mid..hi] is sorted, so the minimum is mid or left of it
    }
  }
  return nums[lo]; // lo === hi points at the minimum
}

