function minEatingSpeed(piles, h) {
  let lo = 1;
  let hi = Math.max(...piles); // eating max(piles) per hour always works
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (hoursNeeded(piles, mid) <= h) hi = mid; // fast enough: try slower
    else lo = mid + 1; // too slow: need a bigger speed
  }
  return lo; // smallest speed that finishes within h hours
}

function hoursNeeded(piles, k) {
  let hours = 0;
  for (const p of piles) hours += Math.ceil(p / k); // a pile takes ceil(p / k) hours
  return hours;
}

def min_eating_speed(piles: list[int], h: int) -> int:
    def hours_needed(k: int) -> int:
        return sum((p + k - 1) // k for p in piles)  # ceil(p / k) per pile

    lo, hi = 1, max(piles)  # eating max(piles) per hour always works
    while lo < hi:
        mid = (lo + hi) // 2
        if hours_needed(mid) <= h:
            hi = mid  # fast enough: try slower
        else:
            lo = mid + 1  # too slow: need a bigger speed
    return lo  # smallest speed that finishes within h hours

public int minEatingSpeed(int[] piles, int h) {
    int lo = 1, hi = 0;
    for (int p : piles) hi = Math.max(hi, p); // max(piles) always works
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (hoursNeeded(piles, mid) <= h) hi = mid; // fast enough: try slower
        else lo = mid + 1; // too slow: need a bigger speed
    }
    return lo;
}

private long hoursNeeded(int[] piles, int k) {
    long hours = 0; // can exceed int range when k is small
    for (int p : piles) hours += (p + (long) k - 1) / k; // ceil(p / k)
    return hours;
}

function searchMatrix(matrix, target) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  let lo = 0;
  let hi = rows * cols - 1; // treat the matrix as one sorted array of rows * cols cells
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    const value = matrix[Math.floor(mid / cols)][mid % cols]; // flat index -> (row, col)
    if (value === target) return true;
    if (value < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return false;
}

def search_matrix(matrix: list[list[int]], target: int) -> bool:
    rows, cols = len(matrix), len(matrix[0])
    lo, hi = 0, rows * cols - 1  # one sorted array of rows * cols cells
    while lo <= hi:
        mid = (lo + hi) // 2
        r, c = divmod(mid, cols)  # flat index -> (row, col)
        value = matrix[r][c]
        if value == target:
            return True
        if value < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

