        if (value == target) return true;
        if (value < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return false;
}

function mySqrt(x) {
  let lo = 0;
  let hi = x;
  let ans = 0;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (mid * mid <= x) {
      ans = mid; // mid fits: remember it and look for a bigger one
      lo = mid + 1;
    } else {
      hi = mid - 1; // mid is too big
    }
  }
  return ans; // largest integer whose square is <= x
}

