function findMedianSortedArrays(a, b) {
  if (a.length > b.length) [a, b] = [b, a]; // binary search the shorter array
  const m = a.length;
  const n = b.length;
  const half = Math.floor((m + n + 1) / 2); // size of the left half
  let lo = 0;
  let hi = m;
  while (lo <= hi) {
    const i = lo + Math.floor((hi - lo) / 2); // elements taken from a
    const j = half - i; // elements taken from b
    const aLeft = i > 0 ? a[i - 1] : -Infinity;
    const aRight = i < m ? a[i] : Infinity;
    const bLeft = j > 0 ? b[j - 1] : -Infinity;
    const bRight = j < n ? b[j] : Infinity;
    if (aLeft <= bRight && bLeft <= aRight) {
      // valid cut: everything on the left is <= everything on the right
      const leftMax = Math.max(aLeft, bLeft);
      if ((m + n) % 2 === 1) return leftMax;
      return (leftMax + Math.min(aRight, bRight)) / 2;
    }
    if (aLeft > bRight) hi = i - 1; // took too many from a
    else lo = i + 1; // took too few from a
  }
  throw new Error('inputs must be sorted');
}

def find_median_sorted_arrays(a: list[int], b: list[int]) -> float:
    if len(a) > len(b):
        a, b = b, a  # binary search the shorter array
    m, n = len(a), len(b)
    half = (m + n + 1) // 2  # size of the left half
    lo, hi = 0, m
    while lo <= hi:
        i = (lo + hi) // 2  # elements taken from a
        j = half - i  # elements taken from b
        a_left = a[i - 1] if i > 0 else float('-inf')
        a_right = a[i] if i < m else float('inf')
        b_left = b[j - 1] if j > 0 else float('-inf')
        b_right = b[j] if j < n else float('inf')
        if a_left <= b_right and b_left <= a_right:  # valid cut
            left_max = max(a_left, b_left)
            if (m + n) % 2 == 1:
                return float(left_max)
            return (left_max + min(a_right, b_right)) / 2
        if a_left > b_right:
            hi = i - 1  # took too many from a
        else:
            lo = i + 1  # took too few from a
    raise ValueError('inputs must be sorted')

public double findMedianSortedArrays(int[] a, int[] b) {
    if (a.length > b.length) return findMedianSortedArrays(b, a); // search the shorter
    int m = a.length, n = b.length, half = (m + n + 1) / 2;
    int lo = 0, hi = m;
    while (lo <= hi) {
        int i = lo + (hi - lo) / 2; // elements taken from a
        int j = half - i; // elements taken from b
        int aLeft = i > 0 ? a[i - 1] : Integer.MIN_VALUE;
        int aRight = i < m ? a[i] : Integer.MAX_VALUE;
        int bLeft = j > 0 ? b[j - 1] : Integer.MIN_VALUE;
        int bRight = j < n ? b[j] : Integer.MAX_VALUE;
        if (aLeft <= bRight && bLeft <= aRight) { // valid cut
            int leftMax = Math.max(aLeft, bLeft);
            if ((m + n) % 2 == 1) return leftMax;
            return (leftMax + (double) Math.min(aRight, bRight)) / 2;
        }
        if (aLeft > bRight) hi = i - 1; // took too many from a
        else lo = i + 1; // took too few from a
    }
    throw new IllegalArgumentException("inputs must be sorted");
}

